+export function prorate(amountCents: number, daysUsed: number, daysInPeriod: number): number {
+  if (daysInPeriod <= 0) throw new RangeError("daysInPeriod must be positive");
+  const ratio = Math.min(Math.max(daysUsed / daysInPeriod, 0), 1);
+  return Math.round(amountCents * ratio);
+}
